import React from 'react';
import { Link } from 'react-router-dom';
import { blogs } from '../../portfolio'
import './BlogList.css'; 

function BlogList() {
    return (
    <div className="blog-list">
        <h1>Blogs</h1>
        <ul>
        {blogs.map((blog) => (
            <li key={blog.id} className="blog-item">
            <Link to={`/blog/${blog.id}`}>
                <h2>{blog.title}</h2>
                <div className="blog-list__hashtags">
                {blog.hashtags.map((hashtag) => (
                  <span key={hashtag} className="blog-list__hashtag">
                    {hashtag}
                  </span>
                ))}
              </div>
            </Link>
            </li>
        ))}
        </ul>
    </div>
    );
}

export default BlogList;
